<?php
require_once 'app_bootstrap.php';require_once 'db.php';require_once 'security.php';require_once 'booking-pricing.php';
if(!customer_is_logged_in())redirect_with_message('reglog.php','Please sign in to view your trips.');
$statusFilter=trim($_GET['status']??'');$statusOptions=['pending','needs_information','confirmed','in_progress','completed','cancelled','rejected'];if($statusFilter!==''&&!in_array($statusFilter,$statusOptions,true))$statusFilter='';
$bookings=[];$travellersByBooking=[];try{$db=db_connect();ensure_app_schema($db);$email=$_SESSION['user_email'];$sql="SELECT b.*,p.name package_name,p.image,p.description package_description,(SELECT status FROM booking_amendments WHERE booking_id=b.id ORDER BY id DESC LIMIT 1) amendment_status,(SELECT status FROM cancellation_requests WHERE booking_id=b.id ORDER BY id DESC LIMIT 1) cancellation_status,(SELECT id FROM booking_reviews WHERE booking_id=b.id LIMIT 1) review_id,(SELECT CONCAT(package_rating,'/',hotel_rating,'/',status) FROM booking_reviews WHERE booking_id=b.id LIMIT 1) review_summary,GROUP_CONCAT(CONCAT(bt.name,IF(bt.relationship IS NULL OR bt.relationship='','',CONCAT(' (',bt.relationship,')'))) ORDER BY bt.id SEPARATOR ', ') traveller_names FROM bookings b LEFT JOIN packages p ON p.id=b.package_id LEFT JOIN booking_travellers bt ON bt.booking_id=b.id WHERE b.user_email=?".($statusFilter!==''?' AND b.status=?':'')." GROUP BY b.id ORDER BY b.created_at DESC";$s=$db->prepare($sql);if($statusFilter!=='')$s->bind_param('ss',$email,$statusFilter);else $s->bind_param('s',$email);$s->execute();$result=$s->get_result();while($row=$result->fetch_assoc()){$bookings[]=$row;$travellersByBooking[(int)$row['id']]=[];}if($travellersByBooking){$ids=implode(',',array_map('intval',array_keys($travellersByBooking)));$travellerResult=$db->query("SELECT booking_id,age_category FROM booking_travellers WHERE booking_id IN ($ids) ORDER BY id");while($travellerResult&&$traveller=$travellerResult->fetch_assoc())$travellersByBooking[(int)$traveller['booking_id']][]=$traveller;}}catch(Throwable $error){$loadError='Your trips are temporarily unavailable.';}$csrf=csrf_token();$bookingActionData=[];foreach($bookings as $bookingAction)$bookingActionData[]=['id'=>(int)$bookingAction['id'],'status'=>$bookingAction['status'],'payment_status'=>$bookingAction['payment_status'],'amendment_status'=>$bookingAction['amendment_status'],'cancellation_status'=>$bookingAction['cancellation_status'],'csrf'=>$csrf];
?>
<!DOCTYPE html><html lang="en"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>My Trips | Travel India</title><link rel="icon" href="img/favicon.jpg?v=1"><link rel="stylesheet" href="css/portal.css?v=16"><script src="js/trip-details.js?v=2" defer></script></head><body class="trips-body"><?php include 'header.php';?>
<main class="portal-page trips-page"><header class="portal-heading"><div><span>Booking history</span><h1>My Trips</h1><p>Track travellers, accommodation, payment, requests, and booking status.</p></div><a class="portal-button" href="Package.php">Explore packages</a></header><nav class="trip-actions" aria-label="Booking status filters"><a class="portal-button secondary <?php echo $statusFilter===''?'active':'';?>" href="my-bookings.php">All</a><?php foreach($statusOptions as $option):?><a class="portal-button secondary <?php echo $statusFilter===$option?'active':'';?>" href="my-bookings.php?status=<?php echo e($option);?>"><?php echo e(ucwords(str_replace('_',' ',$option)));?></a><?php endforeach;?></nav><?php if(!empty($loadError)):?><div class="portal-alert"><?php echo e($loadError);?></div><?php endif;?>
<script>window.bookingActionData=<?php echo json_encode($bookingActionData,JSON_HEX_TAG|JSON_HEX_APOS|JSON_HEX_AMP|JSON_HEX_QUOT);?>;</script><section class="trip-list"><?php if(!$bookings):?><div class="empty-state"><i class="fa-solid fa-suitcase-rolling"></i><h2>No bookings yet</h2><p>Choose an India tour package to create your first trip.</p></div><?php endif;?>
<?php foreach($bookings as $b):$travellerCount=max(1,(int)$b['people']);$hotelUpgrade=max(0,(float)($b['hotel_surcharge_total']??0));$packageSubtotal=max(0,(float)($b['base_amount']??0)-$hotelUpgrade);$packageUnitPrice=(float)($b['package_unit_price']??0);if($packageUnitPrice<=0)$packageUnitPrice=$packageSubtotal/$travellerCount;$priceRows=booking_price_rows_from_travellers($travellersByBooking[(int)$b['id']]??[],$packageUnitPrice,$packageSubtotal,$travellerCount);$discount=max(0,(float)($b['discount_amount']??0));$durationDays=max(1,(new DateTimeImmutable($b['from_date']))->diff(new DateTimeImmutable($b['to_date']))->days+1);?><article class="trip-card detailed-trip"><?php if($b['image']):?><img src="<?php echo e($b['image']);?>" alt="<?php echo e($b['package_name']?:$b['destination']);?>"><?php endif;?><div class="trip-main"><div class="trip-top"><div><span class="reference"><?php echo e($b['booking_reference']?:'Booking #'.$b['id']);?></span><h2><?php echo e($b['package_name']?:$b['destination']);?></h2><p class="trip-destination"><i class="fa-solid fa-location-dot"></i> <?php echo e($b['destination']);?></p></div><span class="status status-<?php echo e($b['status']);?>"><?php echo e(ucwords(str_replace('_',' ',$b['status'])));?></span></div><div class="trip-facts"><span><b>Start date</b><?php echo e(date('d M Y',strtotime($b['from_date'])));?></span><span><b>End date</b><?php echo e(date('d M Y',strtotime($b['to_date'])));?></span><span><b>Duration</b><?php echo $durationDays;?> day<?php echo $durationDays===1?'':'s';?></span><span><b>Hotel</b><?php echo e($b['hotel']);?></span><span><b>Travellers</b><?php echo (int)$b['people'];?></span><span><b>Payment</b><?php echo e(ucfirst($b['payment_status']));?></span><span><b>Requested</b><?php echo e(date('d M Y',strtotime($b['created_at'])));?></span></div><?php if(!empty($b['package_description'])):?><div class="trip-detail trip-package-detail"><b>Package details</b><p><?php echo nl2br(e($b['package_description']));?></p></div><?php endif;?><section class="trip-bill" aria-label="Booking price breakdown"><div class="trip-bill-heading"><div><span>Price summary</span><h3>Booking total</h3></div><strong><?php echo inr($b['total_amount']);?></strong></div><?php echo render_booking_price_rows($priceRows,'trip-bill-row');?><?php if($hotelUpgrade>0):?><div class="trip-bill-row"><span><strong>Hotel upgrade</strong><small><?php echo inr($b['hotel_surcharge_per_traveller']);?> × <?php echo (int)$b['people'];?> traveller<?php echo (int)$b['people']===1?'':'s';?></small></span><strong><?php echo inr($hotelUpgrade);?></strong></div><?php endif;?><?php if($discount>0):?><div class="trip-bill-row trip-bill-discount"><span><strong><?php echo e($b['offer_name']?:($b['offer_code']?:'Offer discount'));?></strong><small>Promotional discount</small></span><strong>-<?php echo inr($discount);?></strong></div><?php endif;?><div class="trip-bill-total"><strong>Total due</strong><strong><?php echo inr($b['total_amount']);?></strong></div></section><?php if($b['traveller_names']):?><div class="trip-detail"><b>Selected travellers</b><p><?php echo e($b['traveller_names']);?></p></div><?php endif;?><?php if($b['customer_note']):?><div class="trip-detail"><b>Your special request</b><p><?php echo e($b['customer_note']);?></p></div><?php endif;?><?php if($b['admin_note']):?><p class="admin-note"><b>Travel India update:</b> <?php echo e($b['admin_note']);?></p><?php endif;?><?php if($b['status']==='completed'):?><div class="trip-actions"><?php if($b['review_id']):?><span class="trip-request-status"><i class="fa-solid fa-star"></i> Review submitted</span><?php else:?><a class="portal-button" href="booking-review.php?booking_id=<?php echo (int)$b['id'];?>"><i class="fa-solid fa-star"></i> Write review</a><?php endif;?></div><?php endif;?></div></article><?php endforeach;?></section></main><?php include 'footer.php';?></body></html>
